insert into public.training_categories (name, sort_order, parent_id)
insert into public.training_categories (name, sort_order, parent_id) select '佩戴问题', 510, '售前话术' where not exists (select 1 from public.training_categories where name='佩戴问题' and parent_id='售前话术');
insert into public.training_categories (name, sort_order, parent_id) select '产品咨询', 520, '售前话术' where not exists (select 1 from public.training_categories where name='产品咨询' and parent_id='售前话术');
insert into public.training_categories (name, sort_order, parent_id) select '订单物流', 530, '售前话术' where not exists (select 1 from public.training_categories where name='订单物流' and parent_id='售前话术');
insert into public.training_categories (name, sort_order, parent_id) select '价格优惠', 550, '售前话术' where not exists (select 1 from public.training_categories where name='价格优惠' and parent_id='售前话术');
insert into public.training_categories (name, sort_order, parent_id) select '平台规则', 560, '售前话术' where not exists (select 1 from public.training_categories where name='平台规则' and parent_id='售前话术');
insert into public.training_categories (name, sort_order, parent_id) select '促单成交', 570, '售前话术' where not exists (select 1 from public.training_categories where name='促单成交' and parent_id='售前话术');
insert into public.training_scripts (category, subcategory, title, styles, tags, sort_order, script_group) values
  ('售前话术', '产品咨询', '直径选择', '{"标准": "咱们常见直径为 14.2mm、14.5mm。眼睛偏小优先 14.2；想要扩瞳效果、眼睛偏大可以选 14.5", "亲切": "宝子，本店美瞳直径主要是 14.2‑14.5mm。14.2 属于中小直径，眼睛偏小选这款；正常 / 大眼睛可选 14.5，您可以参考自己眼型挑选😊", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 1, '通用'),
  ('售前话术', '订单物流', '售前-三幅下单流程', '{"标准": "📋操作步骤：\n\n①分别将 3 副花色，选好度数加入购物车\n\n②购物车内合并结算\n\n✅默认按下单度数发货、不需要修改不同度数的情况下，订单可以不用备注；\n\n💡如果需要调整花色 / 度数，则务必在备注栏写清楚每一副对应的花色 + 度数。", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 2, '通用'),
  ('售前话术', '产品咨询', '半年抛片数', '{"标准": "拍1件是一对，到手【2片】~\n^ 拍3件是三对，到手【6片】~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 3, '通用'),
  ('售前话术', '产品咨询', '半年抛片数', '{"标准": "拍【1件】是【29.9元】，到手1对=2片\n拍【3件】是【39.9元】，到手3对=6片", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 4, '通用'),
  ('售前话术', '订单物流', '告知自身度数-夜间', '{"标准": "好滴~收到您的度数，您可以直接下单宝宝~任意下单一份备注您的不同度数就可以哟~(比如备注:100、200)\n如果没有备注弥小妹帮您记录一下明天一早人工客服上班为您直接备注更换哈，您选好花色任意选择个度数下单就好，不用操作其他咯~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 5, '通用'),
  ('售前话术', '订单物流', '告知自身度数', '{"标准": "好嘞，收到您的度数，我会帮您备注好会尽快发出~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 6, '通用'),
  ('售前话术', '订单物流', '告知自身度数', '{"标准": "好嘞收到，您可以直接下单宝宝~度数我来帮您备注哈\n或者提交订单时【备注栏】，备注您的不同度数就可以~(比如备注:100、200)", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 7, '通用'),
  ('售前话术', '产品咨询', '售前-含水量', '{"标准": "含水 【38%】，含水量并非越高越好，38%的含水更适合长时间佩戴。\n宝喜欢什么色系的？可以帮您挑选花色~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 8, '通用'),
  ('售前话术', '产品咨询', '着色参数', '{"标准": "宝宝~着色直径指的是镜片的有颜色的部分，如果您想要扩瞳效果好，可以选择大直径或者染色直径大的美瞳~如果想要不明显一般选择着色小直径/着色小的美瞳", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 9, '通用'),
  ('售前话术', '产品咨询', '基弧', '{"标准": "宝宝，咱们家的基弧大部分是8.6的弹性基弧，会更符合亚洲人的眼球设计~适合大部分人佩戴~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 10, '通用'),
  ('售前话术', '产品咨询', '镜片厚度', '{"标准": "咱们家美瞳厚度仅 0.07mm左右，属于薄款。这种厚度能最大程度减少异物感，贴合眼球，让宝宝戴上就像没戴一样自然", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 11, '通用'),
  ('售前话术', '产品咨询', '有无高光', '{"标准": "美瞳是有高光设计的，美瞳高光的作用主要是【增加眼睛的亮度】和【立体感】，‌使眼睛看起来更加【有神和自然】。而且我们是双高光的，不会对眼乱转的可以放心购买试戴", "亲切": "宝子~我们的高光做的是对称双高光设计，高光点位稳定不会乱跑，戴上去不会出现对眼、高光歪斜的情况，上眼自然柔和，老客反馈也几乎没反馈转高光问题，可以安心入手试戴~", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 12, '通用'),
  ('售前话术', '订单物流', '备注度数-半年抛', '{"标准": "宝宝~可以备注，任意下单一份备注您的不同度数就可以~(比如备注:100、200)\n或者您直接下单，度数发我，我会帮您备注好~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 13, '通用'),
  ('售前话术', '订单物流', '备注度数-半年抛', '{"标准": "宝宝~可以备注，您的度数发我，我帮您备注好安排发货~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 14, '通用'),
  ('售前话术', '订单物流', '预定下单', '{"标准": "宝宝，因为缺货不能下单，您先拍这个链接同样价格的其他花色代替，帮您备注实发您要的花色，预定的订单到货会优先发货~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 15, '通用'),
  ('售前话术', '价格优惠', '询问赠品', '{"标准": "宝子~赠送的护理液是60ml的", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 16, '通用'),
  ('售前话术', '产品咨询', '售前-小狗心事补货时间', '{"标准": "宝，【小狗心事】预计【9.10号】左右补货，可以帮您做预定，需要吗？\n⚠️当前该花色缺货无法直接下单，方案：\n\n您先拍下 3 副 39.9 活动链接，选店内其他有货花色；\n\n✅ 先发目前现货的美瞳；\n✅【小狗心事】到货后，会优先单独补发这一副，帮您后台备注好。", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 17, '通用'),
  ('售前话术', '产品咨询', '售前-蓝朋友补货时间', '{"标准": "宝，【蓝朋友】预计【9.10号】左右补货，可以帮您做预定哦，需要吗？\n⚠️当前该花色缺货无法直接下单，方案：\n\n您先拍下 3 副 39.9 活动链接，选店内其他有货花色；\n\n✅ 先发目前现货的美瞳；\n✅【蓝朋友】到货后，会优先单独补发这一副，帮您后台备注好。", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 18, '通用'),
  ('售前话术', '产品咨询', '售前-黄油流心补货时间', '{"标准": "宝，【黄油流心】预计【9.8号】左右补货，可以帮您做预定哦，需要吗？\n您先拍下 3 副 39.9 活动链接，选店内其他有货花色；\n\n✅ 先发目前现货的美瞳；\n✅【黄油流心】到货后，会优先单独补发这一副，帮您后台备注好。", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 19, '通用'),
  ('售前话术', '订单物流', '已下单', '{"标准": "好嘞~宝宝，这边先帮您备注上哈，如发货有异常/缺货会联系您~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 20, '通用'),
  ('售前话术', '订单物流', '售前-未下单-帮忙备注', '{"标准": "好嘞~宝宝，您这边先付款，付款后我来操作备注~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 21, '通用'),
  ('售前话术', '佩戴问题', '担心眼睛小', '{"标准": "宝宝，可以戴滴，我们家美瞳的直径一般是适合亚洲人眼球的，直径大一点上眼扩瞳效果也好的~\n您喜欢什么色系的，我帮您推荐几款~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 22, '通用'),
  ('售前话术', '佩戴问题', '担心眼睛小', '{"标准": "宝宝，可以戴滴，我们家美瞳的直径一般是适合亚洲人眼球的，直径大一点上眼扩瞳效果也更好~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 23, '通用'),
  ('售前话术', '佩戴问题', '如何区分左右', '{"标准": "宝子~，隐形按照您的度数来区分左右眼，若您度数相同不需区分左右眼哟~\n美瞳包装上面有显示度数哟", "亲切": "新镜片同样度数的不分左右的，戴了之后取下来存放可以区分左右存放一下，这样会更加卫生宝宝", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 24, '通用'),
  ('售前话术', '订单物流', '修改花色', '{"标准": "可以的宝宝，需要修改的花色度数发我一下下~我来备注好哈", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 25, '通用'),
  ('售前话术', '佩戴问题', '担心敏感眼', '{"标准": "镜片透气水润，对敏感眼比较友好，可以放心购买啦", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 26, '通用'),
  ('售前话术', '订单物流', '忘记备注', '{"标准": "宝子~是可以修改的，您可以直接下单付款，需要修改的发我们，这边为您备注修改哟~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 27, '通用'),
  ('售前话术', '订单物流', '忘记备注', '{"标准": "宝宝，麻烦您提供一下需要修改的花色或者度数~我来修改好", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 28, '通用'),
  ('售前话术', '订单物流', '单买一片', '{"标准": "宝子~半年抛是支持只买一片的，您需要哪个花色度数的~帮您查下库存\n先整幅拍下，记得付款后联系我们备注【只发一片】，到货退【一半的差价】", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 29, '通用'),
  ('售前话术', '订单物流', '询问能够发国外', '{"标准": "宝子~您的地址不支持直达的，不过我们目前支持将商品发往转运仓\n您可以借助转运服务，轻松将宝贝送到国外。您只需在下单时，把收货地址填写为转运仓地址，后续转运公司会帮您将商品寄往国外~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 30, '通用'),
  ('售前话术', '佩戴问题', '适合新手佩戴吗?', '{"标准": "适合新手佩戴的～上手需要少量练习，刚开始不要着急，按照佩戴教程操作，熟悉之后就很好戴啦。", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 31, '通用'),
  ('售前话术', '产品咨询', '询单商品是否磨眼', '{"标准": "宝子，咱们是正规合规美瞳，品控严格，大部分人佩戴反馈都很舒适。每个人眼部感受存在个体差异，美瞳收到支持拆封试戴 1 片，可以放心购买滴😊", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 32, '通用'),
  ('售前话术', '促单成交', '售前-买家表示感谢-未下单', '{"标准": "嘿嘿不客气，还在挑选的话有拿不准的地方可以问我，喜欢就可以直接拍下啦。", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 33, '通用'),
  ('售前话术', '促单成交', '售前-买家表示感谢-已下单', '{"标准": "不客气宝子😊有任何问题随时找我。", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 34, '通用'),
  ('售前话术', '产品咨询', '售前-国民初恋补货时间', '{"标准": "宝，【国民初恋】预计【8.28 】左右补货，可以帮您做预定，需要吗？\n⚠️当前该花色缺货无法直接下单，方案：\n\n您先拍下 3 副 39.9 活动链接，选店内其他有货花色；\n\n✅ 先发目前现货的美瞳；\n✅【国民初恋】到货后，会优先单独补发这一副，帮您后台备注好。", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 35, '通用'),
  ('售前话术', '佩戴问题', '后顶焦度什么意思', '{"标准": "宝宝，后顶焦度就是隐形度数哟。 ☀举个栗子：-1.00就是100度哒~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['通用'], 38, '通用'),
  ('售前话术', '佩戴问题', '佩戴方法', '{"标准": "宝，先洗净双手，把美瞳放指腹上，用另一只手撑开眼皮，轻贴眼球就戴上啦。初次建议佩戴4-5小时，美美戴镜无负担～", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['通用'], 39, '通用'),
  ('售前话术', '产品咨询', '请问双氧护理液只能一般无色隐形眼镜使用吗？', '{"标准": "宝宝双氧水只能透明片使用，是不建议彩片使用的~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['通用'], 42, '通用'),
  ('售前话术', '订单物流', '要新地址', '{"标准": "宝～麻烦提供一下完整新地址哟，需要精确到省市区街道的详细住址，还有收件人姓名和联系方式。有了这些信息一起发我，就可以一键修改咯！", "亲切": "宝~提供下新地址需要包含：省市区街道详细地址，收件人姓名，联系方式，这边尝试修改哟；", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 44, '通用'),
  ('售前话术', '佩戴问题', '吃火锅的时候可以戴吗', '{"标准": "宝子~，一般情况下吃火锅是可以戴隐形眼镜的，不会让隐形融化；\n正规的隐形熔点一般在160摄氏度，亲可以放心啦~ ❤\n但是在高温蒸汽下佩戴隐形会引起眼睛不适，宝宝们要避免油汤溅进眼睛内哟", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['通用'], 62, '通用'),
  ('售前话术', '产品咨询', '会不会加深度数呀', '{"标准": "宝宝，基本上佩戴隐形眼镜【度数是不会增长的】，其实度数增长的罪魁祸首还是用眼姿势及视物光线、用眼过度等问题。和框架眼镜、隐形眼镜一般是没有关系的~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['通用'], 63, '通用'),
  ('售前话术', '佩戴问题', '买家表示摘不下来', '{"标准": "宝宝~别慌！拿纸巾包着硅胶夹子，轻轻一夹一转，利用增大的摩擦力，美瞳就能轻松取下啦，超简单的！\n这次摘美瞳遇到麻烦，以后戴美瞳前滴点润眼液，保持镜片水润，下次摘就不会这么难啦~~", "亲切": "亲爱的别担心，把纸巾包在硅胶夹上，加大摩擦力，慢慢操作，美瞳一下子就能摘下啦 。", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['通用'], 67, '通用'),
  ('售前话术', '佩戴问题', '区分正反', '{"标准": "宝~将镜片放在手指上，边缘内扣像碗是正面，像碟子一样摊开是反面。（可参考图片）", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['通用'], 68, '通用'),
  ('售前话术', '佩戴问题', '区分正反', '{"标准": "宝子~新镜片同样度数的不分左右的哟，戴了之后取下来存放可以区分左右存放一下，这样会更加卫生哒~\n度数不同的话，根据包装上的度数区分左右哟~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['通用'], 69, '通用'),
  ('售前话术', '佩戴问题', '干眼症', '{"标准": "宝宝，有严重的眼部疾病是不建议佩戴隐形的哟（如干眼、结膜炎、沙眼等），建议恢复好后再佩戴的哈 \n眼睛做完手术也是不建议佩戴的（手术后一年才能佩戴隐形） 其他建议您就医询问专业的医生哟~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['通用'], 71, '通用'),
  ('售前话术', '产品咨询', '是否更换护理液', '{"标准": "宝宝，为了眼部健康，如果每天佩戴的话建议护理液最好每天更换一次哈，不佩戴时也要记得定期勤换更换护理液哟", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['通用'], 74, '通用'),
  ('售前话术', '佩戴问题', '可以戴后化妆吗', '{"标准": "宝宝，先戴镜，再化妆，先摘镜，再卸妆~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['通用'], 77, '通用'),
  ('售前话术', '产品咨询', '三明治工艺-舆情防控', '{"标准": "【弥生】所有产品都会使用【三明治工艺】和【内覆膜工艺】，油墨都会在中间，上下层是透明材料，油墨不会直接接触角膜，弥宝的眼睛健康与美丽就由弥生来守护哒～", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['通用'], 79, '通用'),
  ('售前话术', '佩戴问题', '儿童', '{"标准": "❤年龄建议：满18-45周岁可佩戴，如有眼睛疾病如：角膜炎、干眼症等是不建议佩戴的哟~ 男生当然可以佩戴，隐形不分男女的啦~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 80, '通用'),
  ('售前话术', '佩戴问题', '灰尘大', '{"标准": "宝宝，如果您所处的环境比较灰尘比较大的话，建议您不要长时间佩戴美瞳哈，如果灰尘进入到眼睛里面，可能会造成不舒服磨眼的哟", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['通用'], 81, '通用'),
  ('售前话术', '佩戴问题', '感冒', '{"标准": "宝宝，如果有感冒不舒服或者前一天晚上没有休息好的时候，为了咱们眼部眼部健康，尽量不要佩戴美瞳哟~或者注意佩戴时长哟，如果有不舒服及时取下来~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 82, '通用'),
  ('售前话术', '佩戴问题', '运动', '{"标准": "宝宝，一般性的运动都是可以正常佩戴的~如果剧烈运动或者游泳是不建议戴美瞳的哟～ 因为剧烈的运动会出汗，汗液一旦进入到眼睛当中，就会导致细菌和灰尘一同侵入到眼睛当中，可能会出现不舒服~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 83, '通用'),
  ('售前话术', '佩戴问题', '游泳', '{"标准": "游泳不能佩戴：首先，戴隐形眼镜游泳，镜片容易发生脱落丢失；其次，游泳池中的水含有一定的化学成分或者微生物，游泳的过程中很容易进入到眼睛里，镜片会吸附其中的化学物质和微生物，进而刺激角膜、结膜等组织，很容易造成眼部感染。", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 84, '通用'),
  ('售前话术', '佩戴问题', '孕期/姨妈', '{"标准": "宝宝，孕期如果只是拍照或者偶尔出门短时间佩戴是可以哒，不建议长时间佩戴哟~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 85, '通用'),
  ('售前话术', '佩戴问题', '冻住', '{"标准": "宝宝如果发现镜片被冻住，请勿开封，可将其放置在常温处静置解冻哟。（不低于零下15摄氏度）\n常温静置解冻不会对镜片本身性能产生影响，可以放心使用～【小弥特别提示】：\n1. 解冻前切勿开封、摇晃，以免冰渣损坏镜片；\n2.解冻时置于常温处即可，切勿加热或过于靠近热源\n3.镜片解冻后，请在使用前检查确认铝箔包装是否完整；\n4.佩戴前请仔细检查镜片是否完好无损。\n如有任何疑问都可以联系小弥为您尽快处理的～", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['通用'], 86, '通用'),
  ('售前话术', '佩戴问题', '睡午觉', '{"标准": "宝宝，如果您是小睡一会15分钟左右，可以不摘下来的。午睡在半小时以上都建议摘下来哈~不过每个人的眼睛承受能力不同~如果有不舒适的情况，要立马摘下来哟~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 89, '通用'),
  ('售前话术', '订单物流', '发货时间-已付款', '{"标准": "宝子~17点前付款订单当天都会发出的哟，我帮您加急安排哈（如有缺货异常情况会通知您）", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 90, '通用'),
  ('售前话术', '订单物流', '发货时间-未付款', '{"标准": "宝宝~17点前下单都可以发出哟^•ω<^ ੭    ，您尽快付款我来帮您加急安排哟", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 91, '通用'),
  ('售前话术', '订单物流', '发货时间-截单后', '{"标准": "宝宝~仓库是16点截单，今天发不了了  ，不过可以帮您加急安排，明天一早就发出哒~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 92, '通用'),
  ('售前话术', '订单物流', '发货时间-截单后未下单', '{"标准": "宝宝~仓库是16点截单，这会快递正好在仓库收件还没走 ，如果您现在拍下的话还可以帮您加急安排，今天发出哒~\n等会快递走了今天就发不了咯", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 93, '通用'),
