  ('售前话术', '订单物流', '发货地', '{"标准": "宝贝~咱们家是浙江金华发货滴，快递默认发中通/圆通~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['通用'], 95, '通用'),
  ('售前话术', '佩戴问题', '亲，我怎么分辨两盒的度数', '{"标准": "宝宝，度数一般在包装盒的白色塑封标签上会有注明的哟； ▼举个栗子：-3.50即是350度的意思哈~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['通用'], 97, '通用'),
  ('售前话术', '订单物流', '包装要求', '{"标准": "非常抱歉呢，暂时没有礼盒包装的，不过我们美瞳的盒子设计非常精美哒，仓库发货时也会为您检查包装完好发出的哟~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['通用'], 100, '通用'),
  ('售前话术', '价格优惠', '一等奖', '{"标准": "恭喜宝宝中【一等奖】 🎉🎉\n\n奖品是「眼罩单片」，随复购订单发出或晒图领取（有效期14天）\n\n宝宝需要参加的话可以扫码加下专员领取参与哟", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 101, '通用'),
  ('售前话术', '产品咨询', '售前-镜片材质', '{"标准": "宝子，这款是【非离子水凝胶】材质，蛋白不易沉淀，采用三明治锁色工艺，色料夹层不直接接触眼球~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 110, '通用'),
  ('售前话术', '价格优惠', '售前-赠品明细', '{"标准": "宝，咱们的赠品明细请看图片✨买三幅最划算~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 111, '通用'),
  ('售前话术', '价格优惠', '售前-运费险', '{"标准": "✅店铺有赠送运费险，您可直接放心下单，下单页面有显示~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 112, '通用'),
  ('售前话术', '产品咨询', '售前-保质期', '{"标准": "📌宝，美瞳未拆封保质期为 【5 年】\n\n▪这款是半年抛：镜片开封后建议【 6个月内】更换更加卫生；\n\n⚠️半年抛是开封后开始计算使用抛期，并非未拆存放时长哦~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 113, '通用'),
  ('售前话术', '产品咨询', '售前-浸泡时长', '{"标准": "宝，新镜片收到后，建议用护理液充分浸泡 6‑8 小时以上再佩戴，会更加舒适水润。😊", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 114, '通用'),
  ('售前话术', '订单物流', '售前-发货地/发货快递', '{"标准": "宝子😊\n\n📍发货地：浙江\n\n📦默认快递：【圆通】，包邮发出\n\n如需指定【中通】，下单时联系备注即可哦", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 115, '通用'),
  ('售前话术', '产品咨询', '售前-透氧量', '{"标准": "宝子～弥生半年抛 Dk/t 透氧 11.5mmhg。透氧属于镜片参考参数之一，选购优先看花色、度数、直径，再结合自身眼部感受挑选会更合适哦~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 116, '通用'),
  ('售前话术', '订单物流', '售前-别发错了-回复', '{"标准": "✅收到，您的花色、度数信息我已经记录好啦~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 117, '通用'),
  ('售前话术', '平台规则', '售前-试戴规则', '{"标准": "✅宝宝可以放心下单，本店支持【试戴 1 片】的售后权益\n\n⚠️温馨提醒：无论下单几副，整单也仅支持【试戴 1 片】。\n\n试戴后如若佩戴不舒服，及时停止佩戴，先【保留，不要丢弃】试戴镜片和未拆封剩余镜片，可联系我们售后给您处理方案哟；", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 118, '通用'),
  ('售前话术', '订单物流', '售前-不同度数-已付款', '{"标准": "宝，已收到您的付款订单！\n双眼度数不一样的话，把左右眼度数按以下格式告诉我，我帮您备注好。（例：左100 右150）", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 119, '通用'),
  ('售前话术', '订单物流', '售前-不同度数-未付款', '{"标准": "宝宝~半年抛任意下单一份备注您的不同度数就可以~(比如备注:100、200)\n您现在直接下单，度数发我即可，我会帮您备注好~ ​​", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 120, '通用'),
  ('售前话术', '促单成交', '售前-自然花色推荐', '{"标准": "宝宝，咱们自然款主要分【棕色】、【黑色】，您更喜欢什么色系？", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 121, '通用'),
  ('售前话术', '促单成交', '售前-引导下单', '{"标准": "好嘞～您选好直接下单付款即可，付款后提供度数和花色，我帮您后台备注，尽早安排发出。", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 122, '通用'),
  ('售前话术', '产品咨询', '售前-栗栗在逃花色说明', '{"标准": "【栗栗在逃】整体以暖金棕色基底，内圈浅棕色高光使得外圈锁边更佳明显，但过渡自然，实现温柔放大双眼缺不死板~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 123, '通用'),
  ('售前话术', '产品咨询', '售前-小狗心事', '{"标准": "小狗心事：清冷灰蓝调，低饱和不夸张，14.2直径自然扩瞳，上眼是雾蒙蒙的轻混血感，融瞳柔和，日常素颜也能驾驭，眼神通透干净，氛围感拉满~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 124, '通用'),
  ('售前话术', '产品咨询', '售前-是不是正品', '{"标准": "宝子~我们是弥生品牌方，旗下有多家店铺，各店只是主卖产品不同，全部货源统一，均为【弥生正品】。\n资质证件齐全，每盒美瞳都有专属批次流水码可以核验真伪，品质售后所有店铺都是一致，请放心~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 125, '通用'),
  ('售前话术', '产品咨询', '售前-医疗器械注册证', '{"标准": "宝，这是咱们弥生美瞳的医疗器械注册证，美瞳属于三类医疗器械，资质齐全合规，可以放心购买佩戴😊\n店内花色选择丰富，有伪素颜自然款、清透水光款，混血款，您想要什么风格？我帮您挑几款参考。", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['售前'], 126, '通用'),
  ('售前话术', '促单成交', '小直径推荐', '{"标准": "宝，咱们家小直径合集给您参考✨，图里全部都是主流爆款小直径花色，上眼自然不夸张，素颜日常都适配~\n您更喜欢什么色系的呐~", "亲切": "", "简短": "", "专业": "", "安抚": ""}'::jsonb, array['通用'], 127, '通用');